const Tip = ({ active, payload, label }) => {
  if (!active||!payload?.length) return null;
  return (
    <div style={{background:"#0a1428",border:"1px solid rgba(0,207,255,.3)",borderRadius:8,padding:".6rem .85rem"}}>
      <p style={{color:"#00cfff",fontWeight:700,marginBottom:".25rem",fontSize:".76rem"}}>{label}</p>
      {payload.map(p=><p key={p.name} style={{color:p.color,fontSize:".72rem",marginBottom:1}}>{p.name}: <b>{p.value}%</b></p>)}
    </div>
  );
};

